    {
      "step": 3,
      "goal": "State the immediate implementation and review triggers that make the recommendation usable by the cooperative next term.",
      "depends_on": [2]
    }
  ],
  "decisive_step": 2,
  "first_step": {
    "step": 1,
    "derivation": "The problem asks for a single actionable curriculum despite family disagreement and possible deep change. A choice of curriculum presupposes a criterion for ranking options. I treat the criterion as a revisable decision: rank curricula by expected contribution to children's durable capacity to learn, deliberate, and participate across changing technologies and institutions. This is not a content list; it is the rule that will later select content and also makes the later recommendation falsifiable.",
    "result": "Step 1 fixes the operative decision rule: the cooperative should choose next term's curriculum to maximize durable adaptive participation, not to enforce any one family's preferred fixed canon. This rule is provisional and must be stated so that evidence could overturn it.\nCOMMITMENT: Under substantial technological and institutional change, transferable learning and deliberative capacities are more robust curriculum targets than fixed content.",
    "commitments": [
      {
        "kind": "decision",
        "claim": "The cooperative should adopt durable adaptive participation as the primary criterion for ranking next term's curriculum, rather than any single family's preferred fixed canon.",
        "check_or_counterexample": "Contradicted if evidence shows a fixed-canon criterion produces equal or better durable adaptive participation under institutional/technological change, or if durable adaptive participation cannot be operationalized into a next-term choice."
      },
      {
        "kind": "relation",
        "claim": "Under substantial technological and institutional change, transferable learning and deliberative capacities are more robust curriculum targets than fixed content.",
        "check_or_counterexample": "Contradicted if cohorts taught fixed content adapt better to novel institutions/technologies than cohorts taught transferable capacities, or if transferable capacities cannot be distinguished from fixed content in practice."
      }
    ]
  },
  "cannot_decide": null
}

